sketches.source:
setcpm(84/4)

// The form: an intonation, the canzona, an echo, the canzona again, a tutti and a coda
// The repeat group plays canzona, echo, canzona, tutti: 32 bars in all, about a minute and a half
song("intonation@4 (canzona@8 1.echo@4 2.tutti@4)*2 coda@4", "once")
// Steady, then a broad ritardando through the coda
tempomap("0:21 28:21 32:14")

// Two brass choirs face each other across the church, one at each ear, as in the galleries of St Mark's
// In each canzona they answer each other bar by bar, then join for its last four bars
const galleryA = "<1 0 1 0 1 1 1 1>"
const galleryB = "<0 1 0 1 1 1 1 1>"

// One four-bar canzona: C, F, G | Am, F, G | C, F, G | F, G, C
const canzona = note("<[[c4,e4,g4]@3 [c4,e4,g4] [f4,a4,c5]@2 [g4,b4,d5]@2] [[a3,c4,e4]@2 [f3,a3,c4]@2 [g3,b3,d4]@4] [[c4,e4,g4]@2 [e4,g4,c5]@2 [f4,a4,c5]@2 [g4,b4,d5]@2] [[f4,a4,c5]@2 [g4,b4,d5]@2 [e4,g4,c5]@4]>")

// A brass choir, bright or dark, placed at one side of the church
const brass = (x, bright, side) => x.s("sawtooth").unison(2).detune(.1).lpf(bright).lpenv(1.5).lpattack(.05)
  .attack(.04).sustain(.7).release(.3).azimuth(side).distance(4).space("church")

// In the canzona the galleries answer each other: the left bright, the right an octave lower
left: canzona.mask(galleryA).brass(1600, -70).gain(.18).sections("canzona")
right: canzona.add(-12).mask(galleryB).brass(1200, 70).gain(.2).sections("canzona")

// The left gallery intones alone, the right gallery has the echo to itself, and both play the tutti and coda in full
leftFull: canzona.brass(1600, -70).gain(.18).sections("intonation tutti coda")
rightFull: canzona.add(-12).brass(1200, 70).gain(.2).sections("echo tutti coda")

// The organ pedal holds the centre throughout
pedal: note("<[c2@3 c2 f2@2 g2@2] [a1@2 f1@2 g1@4] [c2@4 f2@2 g2@2] [f2@2 g2@2 c2@4]>")
  .s("sawtooth").timbre("organ").lpf(500).attack(.1).sustain(.8).release(.5).space("church").gain(.22)

// Timpani join for the tutti and the coda, and roll in the last bar of each
timpani: s("lt ~ lt ~").speed(.7).lpf(800).room(.6).gain(.4)
  .sections("tutti coda").atEnd(1, x => x.ply(2))

setcpm(72/4)

// The form: a prelude on the pedal, the canon, its double, and a held final chord
song("prelude@2 canon@12 canon'@12 coda@4", "once")
// A ritardando into the last chord
tempomap("0:18 26:18 30:12")

// One theme, three entries a bar apart, each from its own place around your head
// Every strong beat of the theme lands on D, F# or A, so the entries fit over the pedal
const theme = n("<[0 2 4 2] [4 5 4 2] [7 6 7 4] [2@2 1 0]>").scale("D:major")
const bowed = (x, bright = 2600) => x.s("sawtooth").vib(5.5).vibdepth(.1).attack(.04).sustain(.6).release(.25).lpf(bright)

// Each canon restarts the theme, and atStart holds back the later voices, so they enter a bar apart every time
// First violin ahead-left, second violin ahead-right, viola behind you
// In the primed canon every voice plays its double: each note repeated
first: theme.transpose(12).bowed(3200).azimuth(-60).distance(2).room(.4).gain(.2)
  .sections("canon").variant(x => x.ply(2))
second: theme.late(1).bowed().azimuth(60).distance(2).room(.4).gain(.18)
  .sections("canon").atStart(1, x => x.mask("0")).variant(x => x.ply(2))
third: theme.late(2).transpose(-12).bowed(1600).azimuth(180).distance(3).room(.4).gain(.18)
  .sections("canon").atStart(2, x => x.mask("0")).variant(x => x.ply(2))

// The cello holds a D pedal in front of you, and a harpsichord marks the off-beats
cello: note("d2 a1").s("sawtooth").lpf(600).attack(.05).sustain(.6).release(.3).room(.4).gain(.26)
  .exceptSections("coda")
harpsichord: note("[d4,f#4,a4]").struct("~ x ~ x").s("square").pw(.15)
  .decay(.15).sustain(0).lpf(3000).gain(.08).exceptSections("coda")

// The coda: the whole consort on one held D major chord
final: note("[d2,a2,d3,f#3,a3,d4]").slow(4).bowed(1800)
  .attack(.6).release(3).room(.5).gain(.1).sections("coda")

setcpm(60/4)

// The form: an introduction, the song, a middle section in the tenor, the song an octave up, and a coda
song("intro@2 theme@8 middle@8 theme'@8 coda@4", "once")
// The coda slows to a close
tempomap("0:15 26:15 30:10")

// Left hand: broken chords through Eb, Cm, Ab and Bb
left: note("<[eb2 bb2 g3 bb2 eb3 bb2 g3 bb2] [c2 g2 eb3 g2 c3 g2 eb3 g2] [ab1 eb2 c3 eb2 ab2 eb2 c3 eb2] [bb1 f2 d3 f2 bb2 f2 d3 f2]>")
  .s("triangle").timbre("soft").attack(.005).decay(.9).sustain(.1).release(1.2)
  .lpf(1800).room(.5).gain(.3).exceptSections("coda")

// Right hand: the song, always in the centre of your head
// It drops to the tenor in the middle section, and returns an octave higher and softer
right: note("<[g4@3 f4 eb4@2 f4 g4] [eb5@4 d5@2 c5 bb4] [c5@3 bb4 ab4@2 g4 f4] [f4@2 g4 ab4 g4@4]>")
  .s("sine").fm(.8).fmh(2).attack(.01).decay(1.4).sustain(.2).release(1.5)
  .room(.6).gain(.38).add(bysec("middle:-12 *:0"))
  .sections("theme middle").variant(x => x.add(12).gain(.28))

// The strings step through the interaural phase, two bars at a time, starting again in every section
// 0 degrees: centred. 90: looser. 180: diffuse and all around, and nearly gone in mono
pad: note("<[eb3,g3,bb3] [c3,eb3,g3] [ab2,c3,eb3] [bb2,d3,f3]>").s("sawtooth").unison(2).detune(.1)
  .iphase("<0 0 90 90 180 180 90 90>").lpf(1000).attack(1).sustain(1).release(2).gain(.1)
  .exceptSections("coda")

// The coda: a last Eb chord on the piano, and the strings gathered back to the centre
final: note("[eb2,bb2,g3,eb4,g4]").slow(4).s("triangle").timbre("soft")
  .attack(.005).decay(3).sustain(.15).release(3).lpf(1800).room(.6).gain(.2).sections("coda")
padEnd: note("[eb3,g3,bb3]").slow(4).s("sawtooth").unison(2).detune(.1)
  .iphase(0).lpf(1000).attack(1).sustain(1).release(3).gain(.1).sections("coda")

// Rain outside: unrelated noise in each ear, wide and enveloping, all the way through
rain: s("pink").slow(8).icorr(.15).hpf(800).lpf(4000).gain(.03)

setcpm(60/4)

// The form: the low strings alone, the divided passage, a reveal, the divided passage again with a swell, and a coda
// The repeat group plays divided, reveal, divided, swell
song("intro@4 (divided@4 1.reveal@4 2.swell@2)*2 coda@4", "once")
tempomap("0:15 18:15 22:10")

// A violin section at one ear: pan 0 is the left ear, pan 1 the right
const violins = (x, side) => x.s("sawtooth").vib(5).vibdepth(.1).lpf(2800)
  .attack(.04).sustain(.7).release(.2).pan(side).room(.4)

// The melody falls from f#5 and the countermelody rises from d4, but the two sections swap on every note
// Each ear alone hears a jagged line; many listeners hear a high line and a low line that meet and part
firsts: note("f#5 e4 d5 g4 b4 b4 g4 d5").violins(0)
  .gain(bysec("swell:.26 *:.2")).sections("divided swell")
seconds: note("d4 e5 f#4 c#5 a4 a4 c#5 f#4").violins(1)
  .gain(bysec("swell:.26 *:.2")).sections("divided swell")

// The reveal: each ear now plays the smooth line that many listeners heard
high: note("f#5 e5 d5 c#5 b4 b4 c#5 d5").violins(0).gain(.2).sections("reveal")
low: note("d4 e4 f#4 g4 a4 a4 g4 f#4").violins(1).gain(.2).sections("reveal")

// The cellos and basses, the same in both ears
cello: note("d2 a1").s("sawtooth").vib(4.5).vibdepth(.08).lpf(600)
  .attack(.2).sustain(.7).release(.6).room(.5).gain(.26).exceptSections("coda")

// Soft horns hold the harmony in the centre
horns: note("<[d3,a3] [d3,f#3]>").s("triangle").timbre("soft")
  .attack(.8).sustain(.8).release(1.5).room(.6).gain(.12).exceptSections("coda")

// The coda: the whole orchestra settles on D major, the same in both ears
final: note("[d2,a2,d3,f#3,a3]").slow(4).s("sawtooth").vib(4.5).vibdepth(.08).lpf(1800)
  .attack(.6).sustain(.7).release(3).room(.6).gain(.1).sections("coda")

setcpm(48/4)

// The form: the strings alone, the adagio, the adagio again an octave higher, a climax and a coda
song("intro@4 adagio@8 adagio'@8 climax@8 coda@4", "once")
// The coda slows further
tempomap("0:12 28:12 32:8")

// earsh raises the right ear and lowers the left by half the value each, and it widens with each section
// 2 cents beats slowly; 6 and 12 shimmer like a larger section; 30 blooms into a chorus
strings: note("<[bb2,f3,db4,f4] [gb2,db3,bb3,eb4] [ab2,eb3,c4,eb4] [f2,c3,a3,eb4]>").slow(2)
  .s("sawtooth").unison(2).detune(.1).earsh(bysec("intro:2 adagio:6 adagio':12 climax:30"))
  .lpf(1300).attack(2).sustain(1).release(3).room(.7).size(.9).gain(.14)
  .exceptSections("coda")

// A solo violin, the same in both ears, singing over the chords: Bbm, Gb, Ab, F7
// It rises an octave the second time and sings out at the climax
solo: note("<[f4@3 gb4] [ab4@2 gb4 f4] [eb4@4] [db4 eb4 f4@2] [eb4@3 f4] [ab4@2 gb4 eb4] [f4@4] [a4@2 f4@2]>")
  .s("sawtooth").mono(1).glide(.1).vib(5).vibdepth(.15).lpf(2600)
  .attack(.3).sustain(.7).release(1).room(.6).gain(bysec("climax:.22 *:.18"))
  .sections("adagio climax").variant(x => x.add(12))

// The cellos hold the roots, centred
cello: note("<bb1 gb1 ab1 f1>").slow(2).s("sawtooth").vib(4.5).vibdepth(.08)
  .lpf(600).attack(1).sustain(.8).release(2).room(.5).gain(.22).exceptSections("coda")

// The coda: one Bb minor chord, back to a slow 2-cent beat
final: note("[bb1,f2,bb2,db3,f3,bb3]").slow(4).s("sawtooth").unison(2).detune(.1).earsh(2)
  .lpf(1100).attack(1).sustain(1).release(4).room(.7).size(.9).gain(.11).sections("coda")

setcpm(108/4)

// The form: the manual alone, the toccata with pedal, the split chords, the toccata again with everything, and a final chord
song("intro@4 toccata@12 chords@8 toccata'@12 finale@4", "once")
// The final chord broadens
tempomap("0:27 36:27 40:18")

// earsplit("harmonics") alternates the partials between the ears: each ear hears a thinner, hollow organ
// In the primed toccata every note is struck twice
manual: n("0 4 9 4 7 4 9 4").add("<0 -1 -2 -3>").scale("D:minor").transpose(12)
  .s("sawtooth").timbre("organ").earsplit("harmonics")
  .attack(.005).decay(.15).sustain(.4).release(.1).lpf(3000).space("church").gain(.18)
  .exceptSections("finale").variant(x => x.ply(2))

// earsplit("bands") sends the chords' lows to one ear and highs to the other
chords: note("<[d4,f4,a4,d5] [c4,e4,g4,c5] [bb3,d4,f4,bb4] [a3,c4,e4,a4]>").struct("x ~ ~ ~ ~ ~ x ~")
  .s("sawtooth").timbre("organ").earsplit("bands").splitfreq(600)
  .attack(.02).sustain(.6).release(.5).lpf(2400).space("church").gain(.14)
  .sections("chords toccata'")

// The pedal, the same in both ears
pedal: note("<d2 c2 bb1 a1>").s("sawtooth").timbre("organ").lpf(500)
  .attack(.05).sustain(.8).release(.6).space("church").gain(.26)
  .sections("toccata chords")

// The finale: full organ on D major, still split by partials, whole again between your ears
final: note("[d2,a2,d3,f#3,a3,d4]").slow(4).s("sawtooth").timbre("organ").earsplit("harmonics")
  .attack(.05).sustain(.8).release(3).lpf(2400).space("church").gain(.12).sections("finale")

setcpm(56/4)

// The form: an organ prelude, the first verse, an interlude, the second verse and a postlude
song("prelude@4 verse@8 interlude@4 verse'@8 postlude@4", "once")
// The postlude slows to a close
tempomap("0:14 24:14 28:9")

// irate turns the phase between the ears, in turns per second, like a slowly rotating speaker
// Each section turns at its own rate; all rates stay below 3 Hz, so no pulse warning is needed
organ: note("<[c3,e3,g3,c4] [a2,c3,e3,a3] [f2,a2,c3,f3] [g2,b2,d3,g3]>")
  .s("sawtooth").timbre("organ").irate(bysec("prelude:.25 verse:.5 interlude:2 verse':1"))
  .lpf(1200).attack(.4).sustain(.9).release(1).space("church").gain(.16)
  .exceptSections("postlude")

// The hymn on a reed stop, the same in both ears: C, Am, F, G
// In the second verse it moves up an octave on a brighter stop
cantus: note("<[e4@2 d4 c4] [c4@2 e4 a4] [a4@2 g4 f4] [d4@2 b3 d4]>")
  .s("sawtooth").timbre("reed").lpf(1800).attack(.1).sustain(.7).release(.6)
  .space("church").gain(.2)
  .sections("verse").variant(x => x.add(12).lpf(2600).gain(.16))

// The pedal walks the roots, centred
pedal: note("<c2 a1 f1 g1>").s("sawtooth").timbre("organ").lpf(450)
  .attack(.2).sustain(.8).release(1).space("church").gain(.24)
  .exceptSections("postlude")

// The postlude: one C major chord, turning once every four seconds
final: note("[c2,c3,e3,g3,c4]").slow(4).s("sawtooth").timbre("organ").irate(.25)
  .lpf(1000).attack(.4).sustain(.9).release(3).space("church").gain(.13).sections("postlude")

// A bell at the start of each phrase
bell: note("<g4 ~ ~ ~>").s("sine").fm(2).fmh(2.76)
  .decay(3).sustain(0).release(3).space("church").gain(.1)

setcpm(60/3)

// One cycle is a bar of 3/4
// The form: the drone alone, the lullaby, the tune hummed, the lullaby again higher, and a fade
song("drone@4 lullaby@8 humming@8 lullaby'@8 fade@4", "once")
// Slower and slower as it fades
tempomap("0:20 28:20 32:14")

// A 2 Hz binaural drone on an open fifth: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
// It ignores the sections and runs under the whole piece
drone: note("[f1,c2]").slow(8).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.26)

// The cradle song: F, F, C, C, Bb, C7, C, F
const tune = note("<[a4 a4 c5] [a4@2 c5] [g4 f4 g4] [e4@2 c4] [d4 e4 f4] [g4@2 bb4] [a4 g4 e4] [f4@3]>")

// On a music box, floating above your head; the second time an octave higher and softer
musicbox: tune.s("sine").fm(2).fmh(4).attack(.002).decay(1).sustain(0).release(1.5)
  .elevation(40).distance(2).room(.6).size(.85).gain(.2)
  .sections("lullaby").variant(x => x.add(12).gain(.14))

// In the middle, someone hums the tune an octave lower
humTune: tune.add(-12).s("hum").attack(.3).release(1).gain(.12).sections("humming")

// A soft root on each downbeat, and a humming harmony under the music box
bass: note("<f2 f2 c2 c2 bb1 c2 c2 f2>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.2).sections("lullaby humming")
hum: note("<f3 f3 e3 e3 d3 e3 e3 f3>").s("hum").attack(.6).release(1.5).gain(.1)
  .sections("lullaby")

// The fade: one last chime above your head
chime: note("[f4,a4,c5]").slow(4).s("sine").fm(2).fmh(4).attack(.002).decay(3).sustain(0).release(3)
  .elevation(40).distance(2).room(.6).size(.85).gain(.12).sections("fade")

// Crickets far away, all night long
crickets: s("insect").slow(4).distance(8).gain(.06)
